from collections import defaultdict

def count_tilings(grid: list[str]) -> int:
    if not isinstance(grid, list):
        raise ValueError("grid must be a list")

    n_rows = len(grid)
    if n_rows == 0:
        return 1

    n_cols = len(grid[0])

    empty_count = 0
    for row in grid:
        if not isinstance(row, str):
            raise ValueError("grid rows must be strings")
        if len(row) != n_cols:
            raise ValueError("all rows must have the same length")
        for ch in row:
            if ch not in ".#":
                raise ValueError("grid may contain only '.' and '#'")
            if ch == ".":
                empty_count += 1

    if empty_count == 0:
        return 1

    # Choose the smaller direction as the profile width.
    if n_cols > n_rows:
        grid = [
            "".join(grid[r][c] for r in range(n_rows))
            for c in range(n_cols)
        ]
        n_rows, n_cols = n_cols, n_rows

    W = n_cols
    H = n_rows
    ALL = (1 << W) - 1

    block_masks = []
    for row in grid:
        mask = 0
        for c, ch in enumerate(row):
            if ch == "#":
                mask |= 1 << c
        block_masks.append(mask)

    suffix = [(ALL ^ ((1 << i) - 1)) for i in range(W + 1)]

    row_cache: dict[tuple[int, int], list[dict[int, int]]] = {}

    def row_transitions(block: int, next_block: int) -> list[dict[int, int]]:
        key = (block, next_block)
        if key in row_cache:
            return row_cache[key]

        memo: dict[tuple[int, int, int], dict[int, int]] = {}

        def fill(col: int, cur_mask: int, next_mask: int) -> dict[int, int]:
            state = (col, cur_mask, next_mask)
            if state in memo:
                return memo[state]

            if col == W:
                return {next_mask: 1}

            bit = 1 << col
            nxt_bit_next = 1 << (col + 1) if col + 1 < W else 0
            nxt_bit_prev = 1 << (col - 1) if col > 0 else 0
            suffix_next = suffix[col + 1]

            result: dict[int, int] = {}

            def add(new_next: dict[int, int]) -> None:
                for nm, cnt in new_next.items():
                    result[nm] = result.get(nm, 0) + cnt

            # Already occupied/blocked cell: pass over it.
            if block & bit:
                if not (cur_mask & bit):
                    add(fill(col + 1, cur_mask & suffix_next, next_mask))
            elif cur_mask & bit:
                add(fill(col + 1, cur_mask & suffix_next, next_mask))
            else:
                # Horizontal domino.
                if (
                    nxt_bit_next
                    and not (block & nxt_bit_next)
                    and not (cur_mask & nxt_bit_next)
                ):
                    new_cur = (cur_mask | nxt_bit_next) & suffix_next
                    add(fill(col + 1, new_cur, next_mask))

                # Vertical domino.
                if not (next_block & bit) and not (next_mask & bit):
                    add(fill(col + 1, cur_mask & suffix_next, next_mask | bit))

                # L tromino: top-left corner used, missing bottom-right.
                if (
                    nxt_bit_next
                    and not (block & nxt_bit_next)
                    and not (cur_mask & nxt_bit_next)
                    and not (next_block & bit)
                    and not (next_mask & bit)
                ):
                    new_cur = (cur_mask | nxt_bit_next) & suffix_next
                    add(fill(col + 1, new_cur, next_mask | bit))

                # L tromino: top-left corner used, missing bottom-left.
                if (
                    nxt_bit_next
                    and not (block & nxt_bit_next)
                    and not (cur_mask & nxt_bit_next)
                    and not (next_block & nxt_bit_next)
                    and not (next_mask & nxt_bit_next)
                ):
                    new_cur = (cur_mask | nxt_bit_next) & suffix_next
                    add(fill(col + 1, new_cur, next_mask | nxt_bit_next))

                # L tromino: top-left corner used, missing top-right.
                if (
                    nxt_bit_next
                    and not (next_block & bit)
                    and not (next_mask & bit)
                    and not (next_block & nxt_bit_next)
                    and not (next_mask & nxt_bit_next)
                ):
                    add(fill(col + 1, cur_mask & suffix_next, next_mask | bit | nxt_bit_next))

                # L tromino: top-right corner used, missing top-left.
                if (
                    nxt_bit_prev
                    and not (next_block & nxt_bit_prev)
                    and not (next_mask & nxt_bit_prev)
                    and not (next_block & bit)
                    and not (next_mask & bit)
                ):
                    add(
                        fill(
                            col + 1,
                            cur_mask & suffix_next,
                            next_mask | nxt_bit_prev | bit,
                        )
                    )

            memo[state] = result
            return result

        transitions = []
        for prev in range(ALL + 1):
            if prev & block:
                transitions.append({})
            else:
                transitions.append(fill(0, prev, 0))

        row_cache[key] = transitions
        return transitions

    dp: dict[int, int] = {0: 1}

    for r in range(H):
        block = block_masks[r]
        next_block = block_masks[r + 1] if r + 1 < H else ALL
        trans = row_transitions(block, next_block)

        ndp: dict[int, int] = {}
        for prev, ways in dp.items():
            for nxt, cnt in trans[prev].items():
                ndp[nxt] = ndp.get(nxt, 0) + ways * cnt
        dp = ndp

        if not dp:
            return 0

    return dp.get(0, 0)
